 closed_at DATETIME(6), version BIGINT NOT NULL DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 KEY idx_consult_creator(creator_id,status,created_at),
 KEY idx_consult_engineer(current_engineer_id,status),
  CONSTRAINT ck_consultation_status CHECK (status IN ('AI_ACTIVE','WAITING_ENGINEER','HUMAN_ACTIVE','PENDING_CONFIRMATION','RESOLVED','CONVERTED_TO_TICKET','CLOSED')),
 CONSTRAINT ck_consultation_source CHECK (source IN ('AI','HUMAN_DIRECT','TICKET_FOLLOW_UP')),
 CONSTRAINT ck_consultation_resolved_type CHECK (resolved_type IN ('EMPLOYEE_CONFIRMED','AUTO_RESOLVED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE consultation_message (
 message_id VARCHAR(64) PRIMARY KEY, session_id VARCHAR(32) NOT NULL,
 sender_id VARCHAR(64), sender_type VARCHAR(32) NOT NULL, client_message_id VARCHAR(64) NOT NULL,
