 CONSTRAINT ck_ticket_transition_to_status CHECK (to_status IN ('NEW','ASSIGNED','IN_PROGRESS','PENDING_SUPPLEMENT','PENDING_EXTERNAL','PENDING_ACCEPTANCE','COMPLETED','CANCELLED','CLOSED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

