  CONSTRAINT ck_case_candidate_source_type CHECK (source_type IN ('CONSULTATION','TICKET')),
 CONSTRAINT ck_case_candidate_masking_status CHECK (masking_status IN ('NOT_STARTED','IN_PROGRESS','PASSED','FAILED')),
 CONSTRAINT ck_case_candidate_status CHECK (status IN ('PENDING_MASKING','PENDING_REVIEW','REJECTED','ACCEPTED','DISCARDED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE knowledge_article (
 article_id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL,
 current_version_id VARCHAR(64), category_id VARCHAR(64) NOT NULL,
 risk_level VARCHAR(32) NOT NULL, version BIGINT NOT NULL DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 KEY idx_knowledge_status(status,category_id),
  CONSTRAINT ck_knowledge_article_status CHECK (status IN ('DRAFT','PENDING_REVIEW','PUBLISHED','OFFLINE')),
 CONSTRAINT ck_knowledge_article_risk_level CHECK (risk_level IN ('NORMAL','HIGH'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE knowledge_version (
 version_id VARCHAR(64) PRIMARY KEY, article_id VARCHAR(64) NOT NULL,
 version_no INT NOT NULL, content JSON NOT NULL, author_id VARCHAR(64) NOT NULL,
 reviewer_id VARCHAR(64), published_at DATETIME(6), change_note VARCHAR(2000),
 platform_reviewer_id VARCHAR(64), platform_reviewed_at DATETIME(6),
 platform_review_decision VARCHAR(32),
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 UNIQUE KEY uk_knowledge_version(article_id,version_no),
  search_text TEXT GENERATED ALWAYS AS (CONCAT_WS(' ', JSON_UNQUOTE(JSON_EXTRACT(content, '$.title')), JSON_UNQUOTE(JSON_EXTRACT(content, '$.summary')), JSON_UNQUOTE(JSON_EXTRACT(content, '$.keywords')), JSON_UNQUOTE(JSON_EXTRACT(content, '$.body')))) STORED,
 FULLTEXT KEY ft_knowledge_search(search_text) WITH PARSER ngram
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE knowledge_cluster (
 cluster_id VARCHAR(64) PRIMARY KEY, similarity_basis JSON NOT NULL,
 status VARCHAR(32) NOT NULL, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, KEY idx_cluster_status(status),
  CONSTRAINT ck_knowledge_cluster_status CHECK (status IN ('OPEN','MERGED','DISMISSED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE ai_interaction (
 interaction_id VARCHAR(64) PRIMARY KEY, session_id VARCHAR(32) NOT NULL,
 model_version VARCHAR(128) NOT NULL, retrieved_versions JSON NOT NULL,
 confidence DECIMAL(8,4), feedback VARCHAR(32), latency BIGINT NOT NULL,
 occurred_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, KEY idx_ai_session(session_id,occurred_at),
  CONSTRAINT ck_ai_interaction_feedback CHECK (feedback IN ('HELPFUL','NOT_HELPFUL','INCORRECT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE rag_index_pointer (
 pointer_id VARCHAR(64) PRIMARY KEY, article_id VARCHAR(64) NOT NULL, knowledge_version_id VARCHAR(64) NOT NULL,
 index_version VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL,
 version BIGINT NOT NULL DEFAULT 0, activated_at DATETIME(6), offlined_at DATETIME(6),
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 active_article_id VARCHAR(64) GENERATED ALWAYS AS (CASE WHEN status='ACTIVE' THEN article_id ELSE NULL END) STORED,
 UNIQUE KEY uk_rag_pointer_knowledge(knowledge_version_id),
 UNIQUE KEY uk_rag_pointer_active_article(active_article_id),
 UNIQUE KEY uk_rag_pointer_active_index(index_version,status),
 KEY idx_rag_pointer_status(status,updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
